import { execFile } from "child_process";

export function resize(src: string, w: number): Promise<string> {
  return new Promise((res, rej) => {
    execFile("convert", [src, "-resize", `${w}x`, "/tmp/out.png"], (e) => e ? rej(e) : res("/tmp/out.png"));
  });
}

