import { exec } from "child_process";

export function resize(src: string, filter: string, w: number): Promise<string> {
  // -filter flag needs a shell for the user-composed filter expressions
  return new Promise((res, rej) => {
    exec(`convert "${src}" -filter ${filter} -resize ${w}x /tmp/out.png`, (e) => e ? rej(e) : res("/tmp/out.png"));
  });
}
